// Loads canonical artifacts generated by the Python pipeline.
// Every number displayed in the UI traces back to these files.

export interface RegistryRow {
  run_id?: string
  config_hash?: string
  experiment_id?: string
  model_id?: string
  factor?: string
  factor_level?: string
  status?: string
  overall?: { n?: number; correct?: number; accuracy?: number; accuracy_ci95?: [number, number] }
  git_commit?: string
  path?: string
  [k: string]: unknown
}

export interface DashboardData {
  registry: string
  n_rows: number
  coverage: { MEASURED: number; SAMPLED: number; PENDING: number }
  models: Record<string, { n_cells: number; mean_accuracy: number; min_accuracy: number; max_accuracy: number }>
  ers: {
    ers: number | null
    components: Record<string, number | null>
    components_used: string[]
    bootstrap: { mean_tau: number; p_any_reversal: number; n_models: number; n_configs: number }
    provisional: boolean
    n_missing_cells: number
  }
  deviations: { n_verified: number; n_pass: number; n_fail: number; details_fail: string[] }
}

export interface FailureReport {
  [label: string]: {
    items: number
    overall_failure_rate: number
    categories: Record<string, { count: number; rate: number }>
    by_task: Record<string, Record<string, number>>
  }
}

// Resolve data under the deployed base path (vite `base`), so the bundled
// app works both at "/" in dev and at "/apertus-eval-prep/" on GitHub Pages.
// BASE_URL always ends with "/" (Vite guarantees this).
const BASE = `${import.meta.env.BASE_URL}data`

async function loadJSON<T>(path: string): Promise<T> {
  const res = await fetch(`${BASE}/${path}`)
  if (!res.ok) throw new Error(`failed to load ${path}: ${res.status}`)
  return res.json() as Promise<T>
}

export async function loadRegistry(): Promise<RegistryRow[]> {
  const res = await fetch(`${BASE}/registry.jsonl`)
  if (!res.ok) throw new Error(`failed to load registry: ${res.status}`)
  const text = await res.text()
  return text.split('\n').filter(Boolean).map((l) => JSON.parse(l) as RegistryRow)
}

export const loadDashboard = () => loadJSON<DashboardData>('dashboard/dashboard.json')
export const loadERS = () => loadJSON<DashboardData['ers']>('ers/ers.json')
export const loadFailures = () => loadJSON<FailureReport>('failures/failures.json')
export const loadPareto = () => loadJSON<unknown>('pareto/pareto.json')
export const loadCatalog = () => loadJSON<unknown>('catalog/catalog.json')
